      "name": "Chebyshev.primeCounting_sub_theta_div_log_isBigO",
      "type": " : (fun x => ↑⌊x⌋₊.primeCounting - Chebyshev.theta x / Real.log x) =O[Filter.atTop] fun x => x / Real.log x ^ 2",
      "module": "Mathlib.NumberTheory.Chebyshev"
    },
    {
      "name": "Chebyshev.primeCounting_eq_theta_div_log_add_integral",
      "type": " {x : ℝ} (hx : 2 ≤ x) : ↑⌊x⌋₊.primeCounting = Chebyshev.theta x / Real.log x + ∫ (t : ℝ) in 2..x, Chebyshev.theta t / (t * Real.log t ^ 2)",
      "module": "Mathlib.NumberTheory.Chebyshev"
    }
